from __future__ import print_function
import msvcrt
import os
import time
import thread
import threading
char=0
kupey='ÿ'
boneco=[[' ',' ','O'],[' ','<','|','\\',' '],[' ',' ','|'],[' ','/',' ','\\',' '],['|',' ',' ',' ','|']]
posicao_y=11
posicao_x=9
sentido=True

def leituraTeclado():
    global char
    time.sleep(0.01)
    while 1:
        char = msvcrt.getch()

def teclaCima():
    global kupey
    time.sleep(0.02)
    while 1:
        kupey = msvcrt.getch()

def limpaKupey():
    global kupey
    time.sleep(0.03)
    while 1:
        time.sleep(0.01)
        kupey = 'ÿ'
        
def comandosMovimento():
    global char, posicao_x, posicao_y, boneco
    time.sleep(0.04)
    while 1:
        if str(char)=='a':
            if(posicao_x>9):posicao_x -=1
            time.sleep(0.04)
            char=0
        if str(char)=='d':
            if(posicao_x<65):posicao_x +=1
            time.sleep(0.04)
            char=0
        if str(char)=='w':
            if(posicao_y>10):posicao_y -=1
            char=0
        if str(char)=='s':
            if(posicao_y<11):posicao_y +=1
            char=0

def animacaoMovimento():
    global char, boneco, posicao_x, posicao_y, sentido
    time.sleep(0.05)
    while 1:
        if str(char)=='a':
            while str(char)=='a' and posicao_x>9:
                boneco=[[' ',' ','O'],['.','/','|','\\'],[' ',' ','|','`'],[' ','/',' ','\\','_'],['|']]
                time.sleep(0.01)
                boneco=[[' ',' ','O'],[' ','V','|','>'],[' ','_','|'],['|',' ','|'],[' ',' ',' ','\\']]
                time.sleep(0.01)
            boneco=[[' ',' ','O'],[' ','/','|','>'],[' ',' ','|'],[' ','/',' ','\\'],['|',' ',' ',' ','|']]
            sentido=False
        if str(char)=='d':
            while str(char)=='d' and posicao_x<65:
                boneco=[[' ',' ','O'],[' ','/','|','\\','.'],[' ','`','|'],['_','/',' ','\\'],[' ',' ',' ',' ','|']]
                time.sleep(0.01)
                boneco=[[' ',' ','O'],[' ','<','|','V'],[' ',' ','|','_'],[' ',' ','|',' ','|'],[' ','/']]
                time.sleep(0.01)
            boneco=[[' ',' ','O'],[' ','<','|','\\',' '],[' ',' ','|'],[' ','/',' ','\\',' '],['|',' ',' ',' ','|']]
            sentido=True

def golpesAnimacao():
    global char, boneco, posicao_x, posicao_y, sentido,kupey
    time.sleep(0.06)
    ja_deu_soco=False
    while 1:
        if char=='j':
            time.sleep(0.5)
            if kupey=='ÿ' and ja_deu_soco==False:
                if sentido==True:
                    boneco=[[' ',' ','O'],[' ','/','|','V'],[' ','`','|'],[' ',' ','|','\\'],[' ','/',' ',' ','|']]
                    time.sleep(0.05)
                    boneco=[[' ',' ','O','_','_'],[' ','<','|','=','='],[' ',' ','|'],[' ',' ','|','\\'],[' ','/',' ',' ','|']]
                    time.sleep(0.19)
                    boneco=[[' ',' ','O'],[' ','<','|','\\',' '],[' ',' ','|'],[' ','/',' ','\\',' '],['|',' ',' ',' ','|']]
                else:
                    boneco=[[' ',' ','O'],[' ','V','|','\\',],[' ',' ','|','`'],[' ','/','|'],['|',' ',' ','\\']]
                    time.sleep(0.05)
                    boneco=[['_','_','O'],['=','=','|','>'],[' ',' ','|'],[' ','/','|'],['|',' ',' ','\\']]
                    time.sleep(0.19)
                    boneco=[[' ',' ','O'],[' ','/','|','>'],[' ',' ','|'],[' ','/',' ','\\'],['|',' ',' ',' ','|']]
                ja_deu_soco=True
        else:
            ja_deu_soco=False

